<?php
namespace App\Http\Controllers;
use App\Models\AttendanceInput;
use App\Models\Department;
use App\Models\Employee;
use App\Models\JobPosition;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class PayrollEmployeeController extends Controller
{
 public function index(){return view('employees.index',['employees'=>Employee::with(['department','position'])->orderBy('employee_number')->paginate(20)]);}
 public function create(){return view('employees.form',['employee'=>new Employee,'departments'=>Department::with('positions')->orderBy('name')->get()]);}
 public function store(Request $r){$d=$r->validate(['employee_number'=>['required','string','max:40','unique:employees'],'first_name'=>['required','string','max:100'],'last_name'=>['required','string','max:100'],'email'=>['required','email','max:190','unique:employees'],'user_id'=>['nullable','exists:users,id','unique:employees,user_id'],'department_id'=>['required','exists:departments,id'],'job_position_id'=>['required','exists:job_positions,id'],'hired_at'=>['required','date'],'base_minor'=>['required','integer','min:1','max:9000000000000']]);abort_unless(JobPosition::whereKey($d['job_position_id'])->where('department_id',$d['department_id'])->exists(),422,'Position does not belong to selected department.');$base=$d['base_minor'];unset($d['base_minor']);$employee=DB::transaction(function()use($d,$base,$r){$employee=Employee::create($d+['status'=>'active']);$employee->components()->create(['name'=>'Base salary','kind'=>'base','amount_minor'=>$base,'effective_from'=>$d['hired_at']]);\App\Models\PayrollAudit::create(['employee_id'=>$employee->id,'actor_id'=>$r->user()->id,'action'=>'employee.created','details'=>['employee_number'=>$employee->employee_number]]);return $employee;});return redirect()->route('employees.index')->with('success',"Employee {$employee->employee_number} created.");}
 public function edit(Employee $employee){$employee->load('components');return view('employees.form',['employee'=>$employee,'departments'=>Department::with('positions')->orderBy('name')->get()]);}
 public function update(Request $r,Employee $employee){$d=$r->validate(['first_name'=>['required','string','max:100'],'last_name'=>['required','string','max:100'],'email'=>['required','email','max:190',Rule::unique('employees')->ignore($employee->id)],'user_id'=>['nullable','exists:users,id',Rule::unique('employees')->ignore($employee->id,'user_id')],'department_id'=>['required','exists:departments,id'],'job_position_id'=>['required','exists:job_positions,id'],'status'=>['required',Rule::in(['active','terminated'])],'terminated_at'=>['nullable','date']]);abort_unless(JobPosition::whereKey($d['job_position_id'])->where('department_id',$d['department_id'])->exists(),422);$before=$employee->only(array_keys($d));DB::transaction(function()use($d,$employee,$before,$r){$employee->update($d);\App\Models\PayrollAudit::create(['employee_id'=>$employee->id,'actor_id'=>$r->user()->id,'action'=>'employee.updated','details'=>['before'=>$before,'after'=>$d]]);});return back()->with('success','Employee record updated.');}
 public function component(Request $r,Employee $employee){$d=$r->validate(['name'=>['required','string','max:80'],'kind'=>['required',Rule::in(['base','allowance','deduction'])],'amount_minor'=>['required','integer','min:0','max:9000000000000'],'effective_from'=>['required','date'],'effective_until'=>['nullable','date','after_or_equal:effective_from']]);DB::transaction(function()use($d,$employee,$r){if($d['kind']==='base'){$previous=\App\Models\SalaryComponent::where('employee_id',$employee->id)->where('kind','base')->whereNull('effective_until')->where('effective_from','<',$d['effective_from'])->lockForUpdate()->get();foreach($previous as $component)$component->update(['effective_until'=>\Illuminate\Support\Carbon::parse($d['effective_from'])->subDay()->toDateString()]);}$component=$employee->components()->create($d);\App\Models\PayrollAudit::create(['employee_id'=>$employee->id,'actor_id'=>$r->user()->id,'action'=>'salary_component.created','details'=>['component_id'=>$component->id,'kind'=>$component->kind,'amount_minor'=>$component->amount_minor,'effective_from'=>$component->effective_from->toDateString()]]);});return back()->with('success','Effective-dated payroll component added.');}
 public function attendance(Request $r,Employee $employee){$d=$r->validate(['work_date'=>['required','date'],'present'=>['required','boolean'],'overtime_minutes'=>['required','integer','min:0','max:1440']]);abort_if(!$d['present'] && $d['overtime_minutes']>0,422,'Absent days cannot include overtime.');$input=AttendanceInput::updateOrCreate(['employee_id'=>$employee->id,'work_date'=>$d['work_date']],$d+['recorded_by'=>$r->user()->id]);\App\Models\PayrollAudit::create(['employee_id'=>$employee->id,'actor_id'=>$r->user()->id,'action'=>'attendance.saved','details'=>['work_date'=>$input->work_date->toDateString(),'present'=>$input->present,'overtime_minutes'=>$input->overtime_minutes]]);return back()->with('success','Attendance and overtime input saved.');}
}
